INSERT INTO reproduction_limits VALUES(1,'FC26',NULL,'role_demands','선수별 위치 성향의 정밀 재현','EA가 FC26에서 역할 구속을 의도적으로 풀었다("less constrained by their Roles") — (역할×포커스)→히트맵 사상에 고칠 수 없는 상한이 있다','적합 Δ0.02~0.05는 노이즈로 취급하고 숙련도 등 이산 근거로 가른다','docs/20 ① · EA Gameplay Deep Dive · obs#91','HIGH (EA 1차)','2026-09-08');
INSERT INTO reproduction_limits VALUES(2,'FC26',NULL,'pressing','존/맨 마킹 방식과 인계 규칙','FC26 팀 설정에 마킹 방식 축이 없다(수비접근 4종 + 라인 높이뿐)','맨투맨의 실측 서명(전방 볼회수·CB 전진)을 역할·포커스 조합으로 근사(obs#27 창발 방법론)','docs/12 「FC26 구현 함의」 #2 · obs#68','HIGH','2026-09-08');
INSERT INTO reproduction_limits VALUES(3,'FC26',NULL,'pressing','압박 트리거·카운터프레스 강도','압박 강도·트리거 슬라이더가 없다. Aggressive는 「즉시 카운터프레스+오프사이드 트랩」 묶음이라 분리 조절 불가','수비접근 단계 + 라인 높이로 근사, 카운터프레스 실측이 있을 때만 Aggressive','docs/11 「FC26 구현 함의」 #4 · obs#51','HIGH','2026-09-08');
INSERT INTO reproduction_limits VALUES(4,'FC26',NULL,'pressing','실측 PPDA 서열의 그대로 재현','Team Press가 수비 진영에서 너프됐다(2026-05-28) — 압박 강도→설정값 사상이 진영별로 비선형. 손실 순서 AVL < CHE < LIV, 크기는 EA 비공개','압박 국면을 상대 진영에 한정하는 프리셋 검토','docs/20 ⑥ · EA The World''s Game Update · obs#91','HIGH (방향) / 크기 미공개','2026-09-08');
INSERT INTO reproduction_limits VALUES(5,'FC26',NULL,'rotation','주행 부하·일정 밀도에 따른 강도 조절','시즌 누적 피로는 게임에 있으나 전술 설정 축이 아니다','기록만 남기고 재현 대상에서 제외(미결)','docs/11 #5 · docs/12 #3 · obs#56·#73','MEDIUM','2026-09-08');
INSERT INTO reproduction_limits VALUES(6,'FC26',NULL,'formation','공/수 국면별 포메이션 전환(4-2-3-1↔4-4-2, 3-4-2-1↔3-2-5/5-4-1)','FC26은 국면별 포메이션을 갖지 않는다 — 빌드업 스타일·수비접근이 국면을 대신한다','컴팩트=수비접근×라인×역할·포커스의 창발 속성으로 다룬다(obs#27). 국면 분리 실측(cells_poss/cells_def)으로 역할 선택을 국면별로 검증','docs/10 · obs#27·#153','HIGH','2026-09-08');
INSERT INTO reproduction_limits VALUES(7,'FC26',NULL,'set_pieces','세트피스 루틴(니어포스트 과부하·기만 러닝·롱스로)','세트피스 설계 축이 없다 — 키커·타깃 지정 수준','키커·세트피스 타깃 지정, 헤더 도착형 선수 배치','manager_profiles set_pieces(regime 1~3) · report 26','HIGH','2026-09-08');
INSERT INTO reproduction_limits VALUES(8,'FC26',2,'formation','3-4-2-1의 양 윙백','FC26 3-4-2-1의 와이드는 WM 타입이라 윙백 역할(fb_att_wb/fb_inverted)을 선택할 수 없다','5-4-1(FB 슬롯)로 우회하거나 WM 커널 중 전진형 선택 — 처방은 3-4-2-1 유지 중','docs/11 「FC26 구현 함의」 · obs#254','HIGH','2026-09-08');
INSERT INTO reproduction_limits VALUES(9,'FC26',2,'in_possession','2×10이 둘 다 중앙 하프스페이스에 서는 구조','3-4-2-1의 LAM/RAM은 CAM 타입이라 재현되지만 4-2-3-1 어휘로 옮기면 한 명은 WM 커널(터치라인 질량)로 번진다','3-4-2-1 유지 시 문제 없음. 4-2-3-1 변형 프리셋에서만 손실 — 코사인으로 측정 가능(미계산)','docs/11 #3 · obs#59','MEDIUM','2026-09-08');
INSERT INTO reproduction_limits VALUES(10,'FC26',3,'buildup','GK를 우회하는 다이렉트 빌드업(시퀀스당 패스 2.98)','GK의 기점 빈도는 역할 라벨에 없다 — Alisson·Mamardashvili 모두 GK Defend가 최적','빌드업 스타일로만 근사(규칙: 롱볼 비율·점유 → core.team_settings)','docs/12 obs#199 · obs#66','MEDIUM-HIGH','2026-09-08');
INSERT INTO reproduction_limits VALUES(11,'FC26',3,'role_demands','CB·미드필더가 상대 박스까지 따라 올라가는 맨마킹','cb_bpd/Aggressive가 상대 박스까지의 전진을 재현하는지 미검증이며, Team Press 너프(골대에 가까울수록 마킹 느슨)와 정면 충돌','—','docs/12 #5·#6 · obs#69','MEDIUM','2026-09-08');
INSERT INTO reproduction_limits VALUES(12,'FC26',4,'situational','하프타임·경기 중 포메이션 전환(4-1-4-1 → 4-4-2, 61분 3중 교체)','단일 정적 프리셋은 전·후반 차이를 담지 못한다','경기 전용 프리셋은 주도 국면 기준으로 하나만 기록하고 전환 시각을 rationale에 남긴다','docs/13 · report 21·33 · obs#498·#507','MEDIUM','2026-09-08');
INSERT INTO reproduction_limits VALUES(13,'FC26',NULL,'validation','게임 내 재현 결과의 검증(실축 히트맵 ↔ 게임 히트맵)','수동 플레이 환경 — 게임 히트맵은 EA 커널 산출과 사용자 조작의 혼합이다. 조작 선수·볼 배급·팀 설정 3축 체감·기능·도착은 사용자에게 귀속되어 검증 불가. 증명 가능한 것은 비조작 선수의 오프볼 위치 ↔ 선택한 커널의 유사도 하나뿐','비조작 선수만 대조 · 조작 선수는 오염 표기 · 같은 코드 3경기 이상 · 처방 변경 근거로 쓰지 않음(docs/50 「한계」 표)','docs/50 2026-09-08 · 사용자 제기','HIGH','2026-09-08');
INSERT INTO reproduction_limits VALUES(14,'FC26',NULL,'in_possession','rest-defense — 점유 중 볼 뒤에 남겨두는 형태(볼을 잃는 순간의 잔여 수비 배치)','⛔ FC26에 **rest-defense 설정 축이 없다**. 팀 설정 3축(빌드업 스타일·수비 접근·라인 높이)은 **볼을 가진 상태와 잃은 상태를 각각** 규정할 뿐, 「점유 중 뒤에 몇 명을 어떤 모양으로 남기는가」를 직접 지정하지 못한다. ⇒ 하이프레스 팀에서 **압박이 깨진 순간 패스 한 번에 백라인이 노출되는 현상**이 그대로 재현되지 않는다.','⭐ **역할 조합의 창발 속성으로만 간접 조절한다** — ⑴ **피벗 포커스**(dm/cm의 Defend·Ball-Winning ↔ Roaming·Build-Up)가 피벗의 잔류 깊이를 가른다 ⑵ **풀백 전진도**(fb_wingback/Balanced ↔ fb_att_wb/Attack)가 잃는 순간의 폭 노출을 가른다 ⑶ **와이드의 자기진영 질량**(obs#39 뱅크 사다리)이 복귀량을 가른다. ⛔ 세 축을 동시에 만지면 귀속이 안 된다 — 인게임 A/B는 **단일 변수**로(obs#702). ⏰ 측정 방법: 볼 상실 직후 상대 백라인 도달까지의 패스 수를 세는 지표가 우리에게 없다 — **신규 축 후보**.','영상 4소스 독립 지목(obs#774): 67TNBKbdUDw(Red Tactics, LIV) · kURILCR5GQA(Ben Eddy, LIV) · CQfQUokBtQo(talkSPORT, LIV) · K6PKQW16wv0(LockyLeeds, 리즈 관점). + 이라올라 회견 1차(gR_pzueBN2s·xBiwApe6wfk)의 「하이프레스에는 대가가 있다」 맥락.','MEDIUM-HIGH — 4소스가 독립 지목했고 그중 1건은 상대팀(리즈) 관점이라 자기 팀 미화 동기가 없다. ⚠️ 다만 **전부 서사 소스**다(영상·라디오). 실측으로는 아직 측정 지표가 없어(위 workaround ⏰) 「재현 불가」의 정도를 정량화하지 못했다. ⚠️ auto-caption 전사 기반이므로 인용은 원문+번역 병기(불변규칙 11). ⭐ 같은 현상이 **리버풀·리즈 두 팀에서 같은 언어로** 나왔다는 점이 팀 특이성이 아니라 **하이프레스 일반의 대가**임을 시사한다.','2026-09-15');
